from datetime import timedelta
import unittest
from urllib.parse import parse_qs, urlsplit

import calendar_export
import calendar_import
import config
import support


class UniClubsCalendarTests(unittest.TestCase):
    """Use only fixed in-memory calendar text, without storage or provider requests."""

    def event(self, source_id='event-1', **changes):
        """Return one synthetic event carrying the new source namespace."""
        return support.event(event_id=config.UNICLUBS_EVENT_ID_PREFIX + source_id, **changes)

    def test_source_uid_is_distinct_from_legacy_identity(self):
        """A club's source ID cannot be mistaken for an existing integer app event ID."""
        source = self.event('42')
        uid = calendar_export.make_uid(source)
        self.assertEqual(uid, 'weekwise-uniclubs-42@weekwise')
        self.assertNotEqual(uid, calendar_export.make_uid(support.event(event_id=42)))
        self.assertEqual(calendar_import.extract_weekwise_event_id(uid, ''), 'uniclubs:42')
        self.assertEqual(calendar_import.extract_weekwise_event_id(
            calendar_export.make_uid(support.event(event_id=42)), ''), 42)

    def test_source_uid_stays_stable_after_a_date_change(self):
        """Moving the source event to another date must retain the original calendar UID."""
        event = self.event()
        original = calendar_export.make_uid(event)
        moved = self.event(start=event.start + timedelta(days=3),
                           end=event.end + timedelta(days=3), title='Corrected title')
        self.assertEqual(calendar_export.make_uid(moved), original)

    def test_confirmation_export_recognizes_the_namespaced_plan(self):
        """A known source plan must not be imported a second time as a private busy event."""
        event = self.event()
        text = calendar_export.build_ics(event, now=support.NOW)
        start = event.start.date()
        blocks, _, recognized = calendar_import.parse_calendar(
            text, start, start + timedelta(days=1), known_event_ids={event.event_id})
        self.assertEqual(blocks, [])
        self.assertEqual(recognized, {event.event_id})
        blocks, _, recognized = calendar_import.parse_calendar(
            text, start, start + timedelta(days=1))
        self.assertEqual(len(blocks), 1)
        self.assertEqual(blocks[0].title, config.CALENDAR_UNKNOWN_EVENT_TITLE)
        self.assertEqual(recognized, {event.event_id})

    def test_source_cancellation_keeps_the_original_uid(self):
        """Cancellation text must reference the same occurrence without blocking its time."""
        event = self.event()
        text = calendar_export.build_ics(event, cancel=True, now=support.NOW)
        self.assertIn('UID:' + calendar_export.make_uid(event), text)
        self.assertIn('METHOD:CANCEL', text)
        self.assertIn('STATUS:CANCELLED', text)
        blocks, _, recognized = calendar_import.parse_calendar(
            text, event.start.date(), event.start.date() + timedelta(days=1),
            known_event_ids={event.event_id})
        self.assertEqual(blocks, [])
        self.assertEqual(recognized, set())

    def test_provider_reassigned_uid_uses_the_original_description_marker(self):
        """Google and Outlook descriptions keep the source identity after provider UID changes."""
        event = self.event()
        for link, field in ((calendar_export.google_calendar_link(event), 'details'),
                            (calendar_export.outlook_calendar_link(event), 'body')):
            with self.subTest(field=field):
                description = parse_qs(urlsplit(link).query)[field][0]
                self.assertEqual(calendar_import.extract_weekwise_event_id(
                    'provider-assigned-uid', description), event.event_id)

    def test_encoded_source_ids_are_canonical_and_round_trip(self):
        """Encode punctuation and Unicode inside the UID without changing the source identity."""
        event = self.event('zürich/club@event%42')
        uid = calendar_export.make_uid(event)
        self.assertIn('z%C3%BCrich%2Fclub%40event%2542', uid)
        self.assertEqual(calendar_import.extract_weekwise_event_id(uid, ''), event.event_id)

    def test_invalid_source_export_ids_are_rejected(self):
        """Reject empty, oversized, malformed and nonprintable source identities."""
        invalid = ('uniclubs:', 'uniclubs: ', 'uniclubs: leading', 'uniclubs:trailing ',
                   'uniclubs:line\nbreak', 'uniclubs:line\rbreak', 'uniclubs:tab\t',
                   'uniclubs:' + 'x' * (config.UNICLUBS_SOURCE_ID_MAX_CHARS + 1),
                   'other:event-1', '', 0, -1, True)
        for identifier in invalid:
            with self.subTest(identifier=identifier):
                with self.assertRaises(ValueError):
                    calendar_export.make_uid(support.event(event_id=identifier))

    def test_malformed_source_uid_markers_are_not_recognized(self):
        """Reject wrong domains, invalid percent escapes and unsafe decoded marker values."""
        invalid = ('weekwise-uniclubs-@weekwise', 'weekwise-uniclubs-event-1@other',
                   'weekwise-uniclubs-event%ZZ@weekwise',
                   'weekwise-uniclubs-event%2f1@weekwise',
                   'weekwise-uniclubs-%FF@weekwise',
                   'weekwise-uniclubs-%0A@weekwise',
                   'weekwise-uniclubs-%20event@weekwise',
                   'weekwise-uniclubs-zürich@weekwise',
                   'weekwise-uniclubs-event@extra@weekwise')
        for uid in invalid:
            with self.subTest(uid=uid):
                self.assertIsNone(calendar_import.extract_weekwise_event_id(uid, ''))


if __name__ == '__main__':
    unittest.main()
